module dem_hang_doi_fifo_dong_bo_fifo_buffer (
    input  wire             clk,
    input  wire             rst,
    input  wire             enable,
    input  wire             up_down, // 1: Count Up, 0: Count Down
    output reg  [3:0] count,
    output wire             tc       // Terminal Count flag
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'd0;
        end else if (enable) begin
            if (up_down)
                count <= count + 1'b1;
            else
                count <= count - 1'b1;
        end
    end

    assign tc = (up_down && count == {4{1'b1}}) || (!up_down && count == 4'd0);

endmodule
